namespace:
type Address = {
  street: string;
  city: string;
  country: string;
  postalCode?: string;
};

type ContactInfo = {
  name: string;
  email: string;
  address: Address;
};

template.schema:
interface Input {
  recipient: shared.ContactInfo;
  orderNumber: string;
  estimatedDelivery: string;
  items: {
    name: string;
    quantity: integer;
  }[];
}

type Output = string;

interface Input {
  customer: shared.ContactInfo;
  returnReason: "defective" | "wrongItem" | "changedMind" | "other";
  orderNumber: string;
}

type Output = string;
